return Response.json({ page }); }

Headers / cookies: import { headers, cookies } from 'next/headers';

const token = cookies().get('token'); const userAgent = headers().get('user-agent');

1. Динамічні API-роути

```txt
app/api/posts/[id]/route.ts
```

